"""Update only scoped device broker, retry native template and return experiment data."""
import base64,hashlib,http.client,io,json,os,pathlib,pwd,shutil,stat,subprocess,tarfile,time
P=pathlib.Path;BASE=P('/home/jwk/aenv-y-clean-20261111');ROOT=P('/run/jwk-aenv-y-clean-20261111')
UNIT='jwk-aenv-y-clean-20261111.service';BROKER='jwk-aenv-y-devices-20261111.service'
NEW_BROKER='jwk-aenv-y-devices-20261111-017.service'
BUNDLE={'device_broker017.py': {'base64': '', 'sha256': '5bfe4f7c36054f57e29d557e34a2748b21691887842fe2efc65839094356913a'}, 'wikidata017_worker.py': {'base64': '', 'sha256': 'ab8c81860e129367e13ef079088267b2406c26177c5e4a4b433cc0b96af0b8b6'}}
QUERY=r'''
use storage_util::io_ring::spawn_io_ring_worker;
use uvm_ublk::UVMUblkCtrlBuilder;
#[tokio::main(flavor="current_thread")]
async fn main()->Result<(),Box<dyn std::error::Error>>{
 let args:Vec<String>=std::env::args().collect();
 if args.len()!=2||args[1]=="--help"{println!("usage: jwk-ublk-query017 DEVICE_ID (read only kernel owner)");return Ok(());}
 let id:u32=args[1].parse()?;
 let (ring,_)=spawn_io_ring_worker::<io_uring::squeue::Entry128>(0);
 let mut ctrl=UVMUblkCtrlBuilder::new().dev_id(id).name("jwk-owner-query017").build(ring)?;
 ctrl.get_dev_info().await?;
 let uid=ctrl.dev_info.owner_uid;let gid=ctrl.dev_info.owner_gid;let pid=ctrl.dev_info.ublksrv_pid;let flags=ctrl.dev_info.flags;
 println!("{{\"id\":{},\"pid\":{},\"ownerUid\":{},\"ownerGid\":{},\"flags\":{}}}",id,pid,uid,gid,flags);Ok(())
}
'''
def sha(path):
 with path.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def main():
 assert os.getuid()==os.geteuid()==0;os.umask(0o077)
 user=pwd.getpwnam('jwk');assert user.pw_uid==user.pw_gid==1002
 failed=json.loads((BASE/'wikidata015/result.json').read_text());assert not failed['benchmarkRun'] and not failed['success']
 previous=json.loads((BASE/'deployment014/result.json').read_text());inputs=json.loads((BASE/'runtime-prep005/result.json').read_text())
 properties=subprocess.check_output(['systemctl','show',UNIT,'-p','MainPID','-p','ActiveState'],text=True)
 props=dict(line.split('=',1) for line in properties.splitlines());pid=int(props['MainPID'])
 assert props['ActiveState']=='active' and pid==previous['serverPid']
 assert sha(P('/proc',str(pid),'exe'))==inputs['native_inputs']['server']['sha256']
 assert sha(BASE/'config/runtime005.toml')==inputs['service_configuration']['sha256']
 assert sha(BASE/'g4-benchmark_sandbox_lifecycle.py')=='7c26ea29fe8a117859365be18bd8893b1145b3e8c7bf9cdaaeb094a2d0e13263'
 assert P('/proc/sys/kernel/random/boot_id').read_text().strip()==previous['runtime_attestation']['boot_id']
 directory=BASE/'deployment017';assert not directory.exists();directory.mkdir(mode=0o700);os.chown(directory,1002,1002)
 def userfile(path,raw,mode=0o600):
  assert not path.exists() and not path.is_symlink();path.write_bytes(raw.encode() if isinstance(raw,str) else raw);os.chown(path,1002,1002);path.chmod(mode)
 def call(args,seconds=30,env=None):
  r=subprocess.run(list(map(str,args)),env=env or {'PATH':'/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin:/bin:/sbin','LANG':'C.UTF-8'},capture_output=True,text=True,timeout=seconds)
  assert r.returncode==0,{'code':r.returncode,'stderr':r.stderr[-6000:]};return r.stdout
 result={'serviceRestarted':False,'appSourcePatched':False,'kernelChanged':False,'benchmarkRun':False}
 key=(BASE/'config/api-key').read_text().strip()
 try:
  connection=http.client.HTTPConnection('127.0.0.1',18080,timeout=20)
  connection.request('GET','/v2/sandboxes?limit=100',headers={'X-API-Key':key});response=connection.getresponse()
  assert response.status==200 and json.loads(response.read())==[],'Runtime inventory is not empty';connection.close()
  project=directory/'query-helper';project.mkdir(mode=0o700);os.chown(project,1002,1002)
  (project/'src').mkdir(mode=0o700);os.chown(project/'src',1002,1002)
  old=BASE/'runtime-prep003/query-helper'
  userfile(project/'Cargo.toml',(old/'Cargo.toml').read_text().replace('name="jwk-ublk-query"','name="jwk-ublk-query017"'))
  userfile(project/'Cargo.lock',(old/'Cargo.lock').read_bytes());userfile(project/'src/main.rs',QUERY)
  state=json.loads((BASE/'status.json').read_text());tool=P(state['toolchain']['prefix'])
  env={'PATH':str(tool/'bin')+':/usr/bin:/usr/sbin:/bin:/sbin','HOME':user.pw_dir,'USER':'jwk','LOGNAME':'jwk','LANG':'C.UTF-8',
   'CARGO_HOME':str(BASE/'deps/cargo'),'CARGO_TARGET_DIR':str(BASE/'target'),'RUSTC':str(tool/'bin/rustc')}
  with (directory/'helper-build.log').open('xb') as log:
   os.chown(directory/'helper-build.log',1002,1002)
   code=subprocess.run(['runuser','-u','jwk','--',str(tool/'bin/cargo'),'build','--offline','--release','-j','4','--manifest-path',str(project/'Cargo.toml')],env=env,stdout=log,stderr=subprocess.STDOUT,timeout=1200).returncode
  assert code==0,'Read-only owner helper build failed'
  # Keep root-executed helper on a normal executable filesystem, with root-only ancestors.
  install=P('/var/lib/jwk-aenv-y-control017');assert not install.exists();install.mkdir(mode=0o700)
  assert not os.statvfs(install).f_flag&os.ST_NOEXEC,'Helper filesystem is noexec'
  helper=install/'jwk-ublk-query017';helper.write_bytes((BASE/'target/release/jwk-ublk-query017').read_bytes());helper.chmod(0o700)
  result['queryHelp']=call([helper,'--help']);result['helperSha256']=sha(helper)
  result['oldHelperMountFlags']=os.statvfs(ROOT/'jwk-ublk-query').f_flag
  try:
   old_probe=subprocess.run([str(ROOT/'jwk-ublk-query'),'--help'],capture_output=True,text=True,timeout=15)
   result['oldHelperProbe']={'code':old_probe.returncode,'stderr':old_probe.stderr[-2000:]}
  except (OSError,subprocess.TimeoutExpired) as error:result['oldHelperProbe']={'errorType':type(error).__name__,'error':str(error)}
  files={}
  for name,row in BUNDLE.items():
   raw=base64.b64decode(row['base64'],validate=True);assert hashlib.sha256(raw).hexdigest()==row['sha256'];compile(raw,name,'exec');files[name]=raw
  userfile(directory/'wikidata017_worker.py',files['wikidata017_worker.py'],0o700)
  broker_script=ROOT/'device_broker017.py';assert not broker_script.exists();broker_script.write_bytes(files['device_broker017.py']);broker_script.chmod(0o700)
  config=json.loads((ROOT/'broker-config011.json').read_text());assert config['uid']==1002 and config['unit']==UNIT and config['daemon_sha256']==inputs['native_inputs']['daemon']['sha256']
  config.update(gid=1002,query=str(helper))
  config_path=ROOT/'broker-config017.json';assert not config_path.exists();config_path.write_text(json.dumps(config)+'\n');config_path.chmod(0o600)
  old_broker=int(call(['systemctl','show',BROKER,'-p','MainPID','--value']).strip());assert old_broker>0
  old_args=P('/proc',str(old_broker),'cmdline').read_bytes().split(b'\0')
  assert str(ROOT/'device_broker011.py').encode() in old_args and P('/proc',str(old_broker)).stat().st_uid==0
  old_expected=sha(BASE/'runtime-code014/runtime_supervisor014.py')
  result['runtimeSupervisorSha256']=old_expected
  call(['systemctl','stop',BROKER])
  props={'User':'root','UMask':'0077','NoNewPrivileges':'yes','ProtectSystem':'strict','ProtectControlGroups':'yes','ProtectKernelTunables':'yes','ProtectKernelModules':'yes',
   'CapabilityBoundingSet':'CAP_SYS_ADMIN CAP_CHOWN CAP_SYS_PTRACE CAP_DAC_READ_SEARCH','ReadWritePaths':str(ROOT),'MemoryMax':'268435456','TasksMax':'128','LimitNOFILE':'1024',
   'StandardOutput':'append:'+str(ROOT/'broker017.log'),'StandardError':'append:'+str(ROOT/'broker017.log')}
  call(['systemd-run','--unit='+NEW_BROKER,'--description=Independent jwk AgentENV Y owner-verified broker017','--service-type=exec',*['--property='+k+'='+v for k,v in props.items()],'/usr/bin/python3','-I','-B',broker_script],60)
  for _ in range(100):
   if (ROOT/'broker-ready017.json').exists():break
   time.sleep(.1)
  assert (ROOT/'broker-ready017.json').exists(),'New broker readiness failed'
  ca=json.loads((BASE/'config/egress-proxy.json').read_text())['ca']
  env={'PATH':'/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin:/bin:/sbin','HOME':user.pw_dir,'USER':'jwk','LOGNAME':'jwk','LANG':'C.UTF-8','SSL_CERT_FILE':ca,
   'HTTP_PROXY':'http://127.0.0.1:18089','HTTPS_PROXY':'http://127.0.0.1:18089','NO_PROXY':'localhost,127.0.0.1','no_proxy':'localhost,127.0.0.1'}
  command=['nsenter','--target',str(pid),'--net','--mount','--','setpriv','--reuid=1002','--regid=1002','--clear-groups','--inh-caps=-all','--ambient-caps=-all','--bounding-set=-all','--no-new-privs','/usr/bin/python3','-I','-B',str(directory/'wikidata017_worker.py')]
  with (directory/'worker.log').open('xb') as log:code=subprocess.run(command,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=9000).returncode
  result['workerExitCode']=code
  log=(directory/'worker.log').read_text(errors='replace');assert len(log.encode())<1800000;print(log.replace(key,'[REDACTED_API_KEY]'),flush=True)
  assert code==0,'Template or benchmark failed; see included diagnostics'
  result['success']=True;result['benchmarkRun']=True
 except BaseException as error:
  result.update(success=False,errorType=type(error).__name__,error=str(error)[-6000:]);raise
 finally:
  result['diagnostics']={}
  for path in [BASE/'logs/server.log',ROOT/'broker017.log',directory/'helper-build.log']:
   if path.is_file():
    with path.open('rb') as f:f.seek(max(0,path.stat().st_size-26000));result['diagnostics'][str(path)]=f.read().decode(errors='replace').replace(key,'[REDACTED_API_KEY]')
  if not result.get('success') and (BASE/'results/wikidata017').exists():
   archive=io.BytesIO()
   with tarfile.open(fileobj=archive,mode='w:gz') as tar:
    for path in (BASE/'results/wikidata017').rglob('*'):
     if path.is_file() and not path.is_symlink() and path.stat().st_size<8*1024**2:tar.add(path,arcname=str(path.relative_to(BASE/'results/wikidata017')),recursive=False)
   blob=archive.getvalue()
   if len(blob)<1000000:result['failureArtifacts']={'sha256':hashlib.sha256(blob).hexdigest(),'base64':base64.b64encode(blob).decode()}
  userfile(directory/'result.json',json.dumps(result,ensure_ascii=False,indent=2)+'\n')
  print('WIKIDATA_TASK_RESULT='+json.dumps(result,ensure_ascii=False,separators=(',',':')),flush=True)
if __name__=='__main__':main()
